**Plan (read-only analysis - no edits yet):**

1. **Update `src/api/account.ts`**
   - Add imports: `createUser`, `UserError` from `../auth/users.ts`; `createSession` from `../auth/session.ts`
   - Add `POST /api/signup` route in `accountRoutes` array. It reads `email`, `name`, `password` from request body (using `field` like login). Calls `createUser(email, name, password)`. On success: start session via `createSession(user.id)`, respond `201` with `{ token: session.token, user: publicUser(user) }`. If `createUser` throws `UserError`, catch and respond `400` with `{ error: e.message }` (re-throw others).

   **Exact code to write:**

   ```ts
   import { getUser, publicUser, createUser, UserError } from "../auth/users.ts";
   import { revokeSession, createSession } from "../auth/session.ts";
   import { field, html, json, sessionOf, type Route } from "./router.ts";
   import { accountPage } from "../ui/pages.ts";

   export const accountRoutes: Route[] = [
     {
       method: "GET",
       path: "/api/me",
       handler: (req) => {
         const session = sessionOf(req);
         const user = session && getUser(session.userId);
         return user ? json(200, publicUser(user)) : json(401, { error: "not signed in" });
       },
     },
     {
       method: "GET",
       path: "/account",
       handler: (req) => {
         const session = sessionOf(req);
         const user = session && getUser(session.userId);
         return user ? html(200, accountPage(publicUser(user))) : html(401, "<p>Please sign in.</p>");
       },
     },
     {
       method: "POST",
       path: "/api/signup",
       handler: (req) => {
         const email = field(req.body, "email");
         const name = field(req.body, "name");
         const password = field(req.body, "password");
         if (!email || !name || !password) {
           return json(400, { error: "email, name, and password are required" });
         }
         try {
           const user = createUser(email, name, password);
           const session = createSession(user.id);
           return json(201, { token: session.token, user: publicUser(user) });
         } catch (e) {
           if (e instanceof UserError) return json(400, { error: e.message });
           throw e;
         }
       },
     },
     {
       method: "POST",
       path: "/api/logout",
       handler: (req) => {
         const session = sessionOf(req);
         if (!session) return json(401, { error: "not signed in" });
         revokeSession(session.token);
         return json(200, { ok: field(req.body, "reason") ?? true });
       },
     },
   ];
   ```

2. **Add `test/signup.test.ts`**
   - New file mirroring style of `test/api.test.ts` (use `app`, `resetUsers`, `resetSessions`, `call` helper). 
   - Include tests: successful signup creates user and signs in (returns 201 with token and public user); UserError cases return 400 (e.g. invalid email, short password, duplicate email).

   **Exact code to write:**

   ```ts
   import { test, beforeEach } from "node:test";
   import assert from "node:assert/strict";
   import { app } from "../src/api/routes.ts";
   import { resetUsers } from "../src/auth/users.ts";
   import { resetSessions } from "../src/auth/session.ts";

   const call = (method: string, path: string, body?: unknown, token?: string) =>
     app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

   beforeEach(() => {
     resetUsers();
     resetSessions();
   });

   test("signup creates user and signs in", async () => {
     const res = await call("POST", "/api/signup", { email: "bob@example.com", name: "Bob", password: "secretpass" });
     assert.equal(res.status, 201);
     const body = res.body as { token: string; user: { id: string; email: string; name: string } };
     assert.ok(body.token);
     assert.equal(body.user.email, "bob@example.com");
     assert.equal(body.user.name, "Bob");
     assert.ok(body.user.id);
   });

   test("signup returns 400 for invalid email", async () => {
     const res = await call("POST", "/api/signup", { email: "bad", name: "Bad", password: "secretpass" });
     assert.equal(res.status, 400);
     assert.ok(res.body && (res.body as any).error);
   });

   test("signup returns 400 for short password", async () => {
     const res = await call("POST", "/api/signup", { email: "c@example.com", name: "C", password: "short" });
     assert.equal(res.status, 400);
     assert.ok(res.body && (res.body as any).error);
   });

   test("signup returns 400 if email already registered", async () => {
     await call("POST", "/api/signup", { email: "d@example.com", name: "D", password: "secretpass" });
     const res = await call("POST", "/api/signup", { email: "d@example.com", name: "D2", password: "secretpass" });
     assert.equal(res.status, 400);
     assert.ok(res.body && (res.body as any).error);
   });
   ```

3. **Note:** `routes.ts` already spreads `...accountRoutes`, so no change needed there.
